template <typename Range>
class printf_arg_formatter : public detail::arg_formatter_base<Range> {
 public:
  using iterator = typename Range::iterator;

 private:
  using char_type = typename Range::value_type;
  using base = detail::arg_formatter_base<Range>;
  using context_type = basic_printf_context<iterator, char_type>;

  context_type& context_;

  void write_null_pointer(char) {
    this->specs()->type = 0;
    this->write("(nil)");
  }

  void write_null_pointer(wchar_t) {
    this->specs()->type = 0;
    this->write(L"(nil)");
  }

 public:
  using format_specs = typename base::format_specs;

  /**
    \rst
    Constructs an argument formatter object.
    *buffer* is a reference to the output buffer and *specs* contains format
    specifier information for standard argument types.
    \endrst
   */
  printf_arg_formatter(iterator iter, format_specs& specs, context_type& ctx)
      : base(Range(iter), &specs, detail::locale_ref()), context_(ctx) {}

  template <typename T, FMT_ENABLE_IF(fmt::detail::is_integral<T>::value)>
  iterator operator()(T value) {
    // MSVC2013 fails to compile separate overloads for bool and char_type so
    // use std::is_same instead.
    format_specs& fmt_specs = *this->specs();
    if (std::is_same<T, bool>::value && fmt_specs.type == 's') {
        fmt_specs.type = 0;
        const char* bool_text = value ? "true" : "false";
        size_t bool_size = value ? 4u : 5u;
        if (fmt_specs.precision >= 0 &&
            detail::to_unsigned(fmt_specs.precision) < bool_size) {
          bool_size = detail::code_point_index(
              basic_string_view<char>(bool_text, bool_size),
              detail::to_unsigned(fmt_specs.precision));
        }
        size_t display_width = bool_size;
        if (fmt_specs.width != 0) {
          display_width = detail::count_code_points(
              basic_string_view<char>(bool_text, bool_size));
        }
        unsigned spec_width = detail::to_unsigned(fmt_specs.width);
        size_t padding = 0;
        if (spec_width > display_width) {
          padding = spec_width - display_width;
        }
        const char* pad_shifts = detail::data::left_padding_shifts;
        size_t left_padding = padding >> pad_shifts[fmt_specs.align];
        iterator out = this->out();
        auto it = detail::reserve(
            out, bool_size + padding * fmt_specs.fill.size());
        if (fmt_specs.fill.size() == 1) {
          it = std::fill_n(it, left_padding, fmt_specs.fill[0]);
        } else {
          for (size_t fill_index = 0; fill_index < left_padding; ++fill_index)
            it = std::copy_n(fmt_specs.fill.data(), fmt_specs.fill.size(), it);
        }
        it = detail::copy_str<char_type>(bool_text, bool_text + bool_size, it);
        size_t right_padding = padding - left_padding;
        if (fmt_specs.fill.size() == 1) {
          it = std::fill_n(it, right_padding, fmt_specs.fill[0]);
        } else {
          for (size_t fill_index = 0; fill_index < right_padding; ++fill_index)
            it = std::copy_n(fmt_specs.fill.data(), fmt_specs.fill.size(), it);
        }
        return detail::base_iterator(out, it);
    } else if (std::is_same<T, char_type>::value) {
      if (fmt_specs.type && fmt_specs.type != 'c')
        return (*this)(static_cast<int>(value));
      fmt_specs.sign = sign::none;
      fmt_specs.alt = false;
      fmt_specs.align = align::right;
      unsigned spec_width = detail::to_unsigned(fmt_specs.width);
      size_t padding = 0;
      if (spec_width > 1) {
        padding = spec_width - 1;
      }
      const char* pad_shifts = detail::data::left_padding_shifts;
      size_t left_padding = padding >> pad_shifts[fmt_specs.align];
      iterator out = this->out();
      auto it = detail::reserve(out, 1 + padding * fmt_specs.fill.size());
      if (fmt_specs.fill.size() == 1) {
        it = std::fill_n(it, left_padding, fmt_specs.fill[0]);
      } else {
        for (size_t fill_index = 0; fill_index < left_padding; ++fill_index)
          it = std::copy_n(fmt_specs.fill.data(), fmt_specs.fill.size(), it);
      }
      *it++ = static_cast<char_type>(value);
      size_t right_padding = padding - left_padding;
      if (fmt_specs.fill.size() == 1) {
        it = std::fill_n(it, right_padding, fmt_specs.fill[0]);
      } else {
        for (size_t fill_index = 0; fill_index < right_padding; ++fill_index)
          it = std::copy_n(fmt_specs.fill.data(), fmt_specs.fill.size(), it);
      }
      return detail::base_iterator(out, it);
    } else {
    using uint_type = detail::uint32_or_64_or_128_t<T>;
    uint_type abs_value = static_cast<uint_type>(value);
    char prefix[4] = {};
    unsigned prefix_size = 0;
    if (detail::is_negative(value)) {
      prefix[0] = '-';
      prefix_size = 1;
      abs_value = 0 - abs_value;
    } else if (fmt_specs.sign != sign::none && fmt_specs.sign != sign::minus) {
      prefix[0] = fmt_specs.sign == sign::plus ? '+' : ' ';
      prefix_size = 1;
    }

    char type = fmt_specs.type;
    int presentation = 0;
    int num_digits = 0;
    int grouped_size = 0;
    bool upper = false;
    std::string groups;
    char_type sep = 0;
    if (type == 0 || type == 'd') {
      presentation = 0;
      num_digits = detail::count_digits(abs_value);
    } else if (type == 'x' || type == 'X') {
      presentation = 4;
      upper = type != 'x';
      if (fmt_specs.alt) {
        prefix[prefix_size++] = '0';
        prefix[prefix_size++] = type;
      }
      num_digits = detail::count_digits<4>(abs_value);
    } else if (type == 'b' || type == 'B') {
      presentation = 1;
      if (fmt_specs.alt) {
        prefix[prefix_size++] = '0';
        prefix[prefix_size++] = static_cast<char>(type);
      }
      num_digits = detail::count_digits<1>(abs_value);
    } else if (type == 'o') {
      presentation = 3;
      num_digits = detail::count_digits<3>(abs_value);
      if (fmt_specs.alt) {
        if (fmt_specs.precision <= num_digits) {
          if (abs_value != 0) {
            prefix[prefix_size++] = '0';
          }
        }
      }
    } else if (type == 'n' || type == 'L') {
      presentation = -1;
      detail::locale_ref loc;
      groups = detail::grouping<char_type>(loc);
      if (groups.empty()) {
        presentation = 0;
        num_digits = detail::count_digits(abs_value);
      } else {
        sep = detail::thousands_sep<char_type>(loc);
        if (!sep) {
          presentation = 0;
          num_digits = detail::count_digits(abs_value);
        } else {
          num_digits = detail::count_digits(abs_value);
          grouped_size = num_digits;
          std::string::const_iterator group = groups.cbegin();
          while (group != groups.cend()) {
            if (*group > 0) {
              if (*group != detail::max_value<char>()) {
                if (num_digits > *group) {
                  grouped_size += 1;
                  num_digits -= *group;
                  ++group;
                  continue;
                }
              }
            }
            break;
          }
          if (group == groups.cend()) {
            grouped_size += (num_digits - 1) / groups.back();
          }
          num_digits = grouped_size;
        }
      }
    } else {
      FMT_THROW(format_error("invalid type specifier"));
    }

    size_t content_size = prefix_size + static_cast<size_t>(num_digits);
    size_t zero_padding = 0;
    if (fmt_specs.align == align::numeric) {
      unsigned numeric_width = detail::to_unsigned(fmt_specs.width);
      if (numeric_width > content_size) {
        zero_padding = numeric_width - content_size;
        content_size = numeric_width;
      }
    } else if (fmt_specs.precision > num_digits) {
      content_size = prefix_size + detail::to_unsigned(fmt_specs.precision);
      zero_padding = detail::to_unsigned(fmt_specs.precision - num_digits);
    }
    unsigned spec_width = detail::to_unsigned(fmt_specs.width);
    size_t outer_padding = 0;
    if (spec_width > content_size) {
      outer_padding = spec_width - content_size;
    }
    const char* pad_shifts = detail::data::right_padding_shifts;
    size_t left_padding = outer_padding >> pad_shifts[fmt_specs.align];
    iterator out = this->out();
    auto it = detail::reserve(
        out, content_size + outer_padding * fmt_specs.fill.size());
    if (fmt_specs.fill.size() == 1) {
      it = std::fill_n(it, left_padding, fmt_specs.fill[0]);
    } else {
      for (size_t fill_index = 0; fill_index < left_padding; ++fill_index)
        it = std::copy_n(fmt_specs.fill.data(), fmt_specs.fill.size(), it);
    }
    if (prefix_size != 0) {
      it = detail::copy_str<char_type>(prefix, prefix + prefix_size, it);
    }
    if (zero_padding != 0) {
      it = std::fill_n(it, zero_padding, static_cast<char_type>('0'));
    }
    if (presentation == 0) {
      enum { max_size = detail::digits10<uint_type>() + 1 };
      char_type digit_buffer[2 * max_size];
      char_type* digit_ptr = digit_buffer + num_digits;
      uint_type remaining = abs_value;
      while (remaining >= 100) {
        unsigned index = static_cast<unsigned>((remaining % 100) * 2);
        remaining /= 100;
        *--digit_ptr = static_cast<char_type>(detail::data::digits[index + 1]);
        *--digit_ptr = static_cast<char_type>(detail::data::digits[index]);
      }
      if (remaining < 10) {
        *--digit_ptr = static_cast<char_type>('0' + remaining);
      } else {
        unsigned index = static_cast<unsigned>(remaining * 2);
        *--digit_ptr = static_cast<char_type>(detail::data::digits[index + 1]);
        *--digit_ptr = static_cast<char_type>(detail::data::digits[index]);
      }
      it = detail::copy_str<char_type>(digit_ptr, digit_buffer + num_digits, it);
    } else if (presentation == 4) {
      it = detail::format_uint<4, char_type>(it, abs_value, num_digits, upper);
    } else if (presentation == 1) {
      it = detail::format_uint<1, char_type>(it, abs_value, num_digits);
    } else if (presentation == 3) {
      it = detail::format_uint<3, char_type>(it, abs_value, num_digits);
    } else {
      int digit_index = 0;
      std::string::const_iterator group_it = groups.cbegin();
      char_type sep_ch = sep;
      auto add_sep = [&](char_type*& buffer) {
        if (*group_it <= 0 || ++digit_index % *group_it != 0 ||
            *group_it == detail::max_value<char>())
          return;
        if (group_it + 1 != groups.cend()) {
          digit_index = 0;
          ++group_it;
        }
        --buffer;
        *buffer = sep_ch;
      };
      it = detail::format_decimal<char_type>(it, abs_value, grouped_size,
